import numpy as np

def step(l,w,s):
    # recurrence monic OP via orthonormal Lanczos
    q=np.ones(len(l)); prev=np.zeros(len(l)); beta=0
    for j in range(s):
        a=np.dot(w,q*q*l)
        z=(l-a)*q-beta*prev
        beta=np.sqrt(np.dot(w,z*z)); prev,q=q,z/beta
    v=w*q*q
    return v/v.sum()
